       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the quality permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
