            ('quality_inspection_reading:purge'::text, 'quality_inspection_reading'::text, 'purge'::text, 'Purge quality inspection reading'::text),
            ('quality_inspection_reading:read'::text, 'quality_inspection_reading'::text, 'read'::text, 'Read quality inspection reading'::text),
            ('quality_inspection_reading:restore'::text, 'quality_inspection_reading'::text, 'restore'::text, 'Restore quality inspection reading'::text),
            ('quality_inspection_reading:update'::text, 'quality_inspection_reading'::text, 'update'::text, 'Update quality inspection reading'::text),
