            ('quality_inspection_template:delete'::text, 'quality_inspection_template'::text, 'delete'::text, 'Delete quality inspection template'::text),
            ('quality_inspection_template:purge'::text, 'quality_inspection_template'::text, 'purge'::text, 'Purge quality inspection template'::text),
